    insert into public.missions (slug, mission_no, emoji, title, category_id, stages, reward_rules, engine_options, status)
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'story', null, 0, $j${"emoji":"🧑🏾‍🔧","title":{"ha":"Sannu, ƙaramin mai ƙirƙira! 👋","en":"Hello, young inventor! 👋"},"lines":[{"text":{"ha":"Wani manomi ya girbe rogo da yawa.","en":"A farmer harvested lots of cassava."}},{"text":{"ha":"Yana son ya san abubuwan da za a iya samarwa daga rogon. Za ka iya taimaka masa?","en":"He wants to know what can be made from it. Can you help him?"}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 1, $j${"emoji":"🌍","title":{"ha":"Abu na asali da sabon abu","en":"Resource and new product"},"lines":[{"text":{"ha":"Abu na asali yana fitowa daga yanayi. Misali: rogo, ruwa.","en":"A resource comes from nature. Example: cassava, water."}},{"text":{"ha":"Sabon abu ana yin shi daga abu na asali. Misali: garri daga rogo.","en":"A new product is made from a resource. Example: garri from cassava."}},{"text":{"ha":"Abu na asali → Sarrafawa → Sabon abu → Amfani","en":"Resource → Processing → New product → Value"}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 2, $j${"emoji":"🌱","title":{"ha":"Rogo","en":"Cassava"},"lines":[{"k":"whatIs","text":{"ha":"Rogo tushe ne da ke girma a gona.","en":"Cassava is a root that grows in the field."}},{"k":"whatDoes","text":{"ha":"Ana ci bayan an sarrafa shi.","en":"We eat it after it is processed."}},{"k":"whyNeeded","text":{"ha":"Mu sarrafa shi don kada ya lalace kuma ya zama mai amfani.","en":"We process it so it does not spoil and becomes useful."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 3, $j${"emoji":"⚠️","warn":true,"title":{"ha":"Tsaro","en":"Safety"},"lines":[{"text":{"ha":"Rogo danye zai iya zama guba idan ba a sarrafa shi daidai ba.","en":"Raw cassava can be poisonous if it is not processed the right way."}},{"text":{"ha":"Kada ka yi da kanka. Manya masu horo ne kawai ya kamata su sarrafa shi. Wannan wasa ne kawai.","en":"Never try it yourself. Only trained adults should process it. This is a game only."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 4, $j${"emoji":"🥣","title":{"ha":"Garri","en":"Garri"},"lines":[{"k":"whatIs","text":{"ha":"Busasshen hatsi ƙanana daga rogo.","en":"Dry tiny grains made from cassava."}},{"k":"whatDoes","text":{"ha":"Ana jiƙa shi da ruwa a sha, ko a yi eba.","en":"Soak it in water to drink, or make eba."}},{"k":"whyNeeded","text":{"ha":"Yana daɗewa idan an ajiye shi a busasshe.","en":"It lasts long when kept dry."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 5, $j${"emoji":"🍲","title":{"ha":"Fufu","en":"Fufu"},"lines":[{"k":"whatIs","text":{"ha":"Taliya mai laushi daga rogo da ya yi tsami.","en":"Soft dough from soured cassava."}},{"k":"whatDoes","text":{"ha":"Ana ci da miya.","en":"We eat it with soup."}},{"k":"whyNeeded","text":{"ha":"Tsami yana sauya ɗanɗano kuma yana sa shi laushi.","en":"Souring changes the taste and makes it soft."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 6, $j${"emoji":"🌾","title":{"ha":"Garin rogo","en":"Cassava flour"},"lines":[{"k":"whatIs","text":{"ha":"Farin gari mai laushi daga busasshen rogo.","en":"Soft white powder from dried cassava."}},{"k":"whatDoes","text":{"ha":"Ana yin burodi ko kunun da shi.","en":"Used for baking and porridge."}},{"k":"whyNeeded","text":{"ha":"Gari ya fi sauƙin ɗauka da ajiya fiye da rogo danye.","en":"Flour is easier to carry and store than fresh roots."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 7, $j${"emoji":"🥛","title":{"ha":"Sitaci","en":"Starch"},"lines":[{"k":"whatIs","text":{"ha":"Farin gari da ake raba daga ruwan rogo.","en":"White powder separated from cassava water."}},{"k":"whatDoes","text":{"ha":"Ana dafa abinci, wanki, da yin manna da shi.","en":"Used for cooking, laundry and glue."}},{"k":"whyNeeded","text":{"ha":"Sitaci yana zama a ƙasan ruwa, don haka ana iya raba shi.","en":"Starch sinks in water, so it can be separated."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 8, $j${"emoji":"💰","title":{"ha":"Sarrafawa yana ƙara ƙima","en":"Processing adds value"},"lines":[{"text":{"ha":"Rogo danye yana da arha kuma yana lalacewa da sauri.","en":"Raw cassava is cheap and spoils quickly."}},{"text":{"ha":"Garri, fufu, gari da sitaci suna da ƙima fiye, kuma ana iya sayar da su.","en":"Garri, fufu, flour and starch are worth more and can be sold."}},{"text":{"ha":"Kowanne yana da hanyarsa ta sarrafawa. Za ka kalle su duka.","en":"Each one has its own way of being made. You will watch them all."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'peel', 0, $j${"emoji":"🔪","name":{"ha":"Feɗe","en":"Peel"},"text":{"ha":"Manya suna cire bawon rogo.","en":"Adults remove the cassava skin."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'wash', 1, $j${"emoji":"🚿","name":{"ha":"Wanke","en":"Wash"},"text":{"ha":"Ana wanke rogon da ruwa mai tsabta.","en":"The cassava is washed with clean water."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'grate', 2, $j${"emoji":"⚙️","name":{"ha":"Markaɗa","en":"Grate"},"text":{"ha":"Ana markaɗa rogon ya zama gauraye mai danshi.","en":"The cassava is grated into a wet pulp."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'pressFerment', 3, $j${"emoji":"🪨","name":{"ha":"Matse, a bar ya yi tsami","en":"Press and sour"},"text":{"ha":"Ana matse ruwan, a bar gaurayen ya yi tsami na kwanaki.","en":"The water is pressed out and the pulp sours for days."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'sieve', 4, $j${"emoji":"🧺","name":{"ha":"Tace","en":"Sieve"},"text":{"ha":"Ana tace shi don ya yi laushi daidai.","en":"It is sieved so the grains are even."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'roast', 5, $j${"emoji":"🔥","name":{"ha":"Soya a kaskon","en":"Roast in a pan"},"text":{"ha":"Manya suna soya shi a kaskon har ya bushe.","en":"Adults roast it in a pan until dry."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'coolPack', 6, $j${"emoji":"📦","name":{"ha":"Sanyaya a ƙunshe","en":"Cool and pack"},"text":{"ha":"Ana barin shi ya huce, sai a saka a jaka.","en":"It cools down, then goes into a bag."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'soak', 7, $j${"emoji":"💧","name":{"ha":"Jiƙa a bar ya yi tsami","en":"Soak and sour"},"text":{"ha":"Ana jiƙa rogo a ruwa har ya yi tsami da laushi.","en":"The cassava soaks in water until soft and sour."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'mash', 8, $j${"emoji":"🥄","name":{"ha":"Dake a tace","en":"Mash and sieve"},"text":{"ha":"Ana dake shi a tace, a cire zaruruwa.","en":"It is mashed and sieved to remove fibres."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'drain', 9, $j${"emoji":"🫗","name":{"ha":"Zubar da ruwan","en":"Pour off the water"},"text":{"ha":"Ana zubar da ruwan a bar gaurayen.","en":"The water is poured off and the pulp stays."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'cook', 10, $j${"emoji":"🍲","name":{"ha":"Dafa ya yi laushi","en":"Cook until soft"},"text":{"ha":"Manya suna dafa shi har ya zama taliya mai laushi.","en":"Adults cook it until it becomes soft dough."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'chip', 11, $j${"emoji":"✂️","name":{"ha":"Yanka ƙananan guda","en":"Cut small pieces"},"text":{"ha":"Ana yanka rogo ƙanana don ya bushe da sauri.","en":"Cassava is cut small so it dries fast."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'dry', 12, $j${"emoji":"☀️","name":{"ha":"Busar da shi sosai","en":"Dry it well"},"text":{"ha":"Ana busar da shi sosai a rana ko da na’ura.","en":"It is dried well in the sun or by a machine."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'mill', 13, $j${"emoji":"🏭","name":{"ha":"Niƙa ya zama gari","en":"Grind to powder"},"text":{"ha":"Ana niƙa busasshen rogo ya zama gari.","en":"The dry cassava is ground into flour."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'pack', 14, $j${"emoji":"📦","name":{"ha":"Ƙunshe","en":"Pack"},"text":{"ha":"Ana saka shi a jaka mai tsabta.","en":"It goes into a clean bag."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'rinse', 15, $j${"emoji":"🌊","name":{"ha":"Wanke gaurayen a tace","en":"Rinse pulp through a sieve"},"text":{"ha":"Ana wanke gaurayen ta cikin tace. Ruwan fari yana ɗauke da sitaci.","en":"The pulp is rinsed through a sieve. The white water carries starch."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'settle', 16, $j${"emoji":"⏳","name":{"ha":"A bar sitaci ya zauna","en":"Let the starch settle"},"text":{"ha":"Ana barin ruwan, sitaci kuma yana zama a ƙasa.","en":"The water rests and the starch sinks to the bottom."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'procedure', 'demonstration', 'garri', 0, $j${"id":"garri","emoji":"🥣","name":{"ha":"Garri","en":"Garri"},"steps":["peel","wash","grate","pressFerment","sieve","roast","coolPack"],"result":{"emoji":"🥣","name":{"ha":"Garri","en":"Garri"}},"summary":{"ha":"Garri yana buƙatar tsami da soyawa.","en":"Garri needs souring and roasting."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'procedure', 'demonstration', 'fufu', 1, $j${"id":"fufu","emoji":"🍲","name":{"ha":"Fufu","en":"Fufu"},"steps":["peel","wash","soak","mash","drain","cook"],"result":{"emoji":"🍲","name":{"ha":"Fufu","en":"Fufu"}},"summary":{"ha":"Fufu yana buƙatar jiƙa da dafawa. Ba a soya shi.","en":"Fufu needs soaking and cooking. It is not roasted."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'procedure', 'demonstration', 'flour', 2, $j${"id":"flour","emoji":"🌾","name":{"ha":"Garin rogo","en":"Cassava flour"},"steps":["peel","wash","chip","dry","mill","sieve","pack"],"result":{"emoji":"🌾","name":{"ha":"Garin rogo","en":"Cassava flour"}},"summary":{"ha":"Garin rogo yana buƙatar bushewa da niƙa.","en":"Cassava flour needs drying and grinding."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'procedure', 'demonstration', 'starch', 3, $j${"id":"starch","emoji":"🥛","name":{"ha":"Sitaci","en":"Starch"},"steps":["peel","wash","grate","rinse","settle","dry","pack"],"result":{"emoji":"🥛","name":{"ha":"Sitaci","en":"Starch"}},"summary":{"ha":"Sitaci yana buƙatar wanki da barin ya zauna a ƙasa.","en":"Starch needs rinsing and settling."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'challenge', 'drag_drop', 'sort', 0, $j${"type":"sort","key":"sort","items":[{"emoji":"🌱","kind":"resource","name":{"ha":"Rogo a gona","en":"Cassava in the field"},"why":{"ha":"Rogo yana girma a gona. Abu na asali ne.","en":"Cassava grows in the field. It is a resource."}},{"emoji":"🥣","kind":"product","name":{"ha":"Garri","en":"Garri"},"why":{"ha":"Ana yin garri daga rogo. Sabon abu ne.","en":"Garri is made from cassava. It is a new product."}},{"emoji":"💧","kind":"resource","name":{"ha":"Ruwa","en":"Water"},"why":{"ha":"Ruwa yana fitowa daga yanayi. Abu na asali ne.","en":"Water comes from nature. It is a resource."}},{"emoji":"🥛","kind":"product","name":{"ha":"Sitaci","en":"Starch"},"why":{"ha":"Ana raba sitaci daga rogo. Sabon abu ne.","en":"Starch is separated from cassava. It is a new product."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'challenge', 'challenge', 'business', 1, $j${"type":"business","key":"business"}$j$::jsonb);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 0, $j${"ha":"Menene sarrafawa ke yi wa rogo?","en":"What does processing do to cassava?"}$j$::jsonb, $j$[{"ha":"Yana mai da shi sabon abu mai amfani","en":"Turns it into a useful new product"},{"ha":"Yana sa ya ɓace","en":"Makes it disappear"},{"ha":"Yana sa shi ya zama guba","en":"Makes it poisonous"}]$j$::jsonb, 0, $j${"ha":"Sarrafawa yana mai da rogo sabon abu, kamar garri.","en":"Processing turns cassava into a new product, like garri."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 1, $j${"ha":"Me ya sa ba a cin rogo danye?","en":"Why do we not eat raw cassava?"}$j$::jsonb, $j$[{"ha":"Ya yi sanyi sosai","en":"It is too cold"},{"ha":"Zai iya zama guba","en":"It can be poisonous"},{"ha":"Ba shi da ɗanɗano","en":"It has no taste"}]$j$::jsonb, 1, $j${"ha":"Rogo danye zai iya zama guba. Shi ya sa manya masu horo ne ke sarrafa shi.","en":"Raw cassava can be poisonous. That is why trained adults process it."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 2, $j${"ha":"Wane ne ake soyawa a kaskon?","en":"Which one is roasted in a pan?"}$j$::jsonb, $j$[{"ha":"Garri","en":"Garri"},{"ha":"Fufu","en":"Fufu"},{"ha":"Sitaci","en":"Starch"}]$j$::jsonb, 0, $j${"ha":"Ana soya garri. Fufu ana dafa shi, sitaci kuma ana barin shi ya zauna a ƙasa.","en":"Garri is roasted. Fufu is cooked, and starch is left to settle."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 3, $j${"ha":"Wane ne ake busarwa a niƙa ya zama gari?","en":"Which one is dried and ground into powder?"}$j$::jsonb, $j$[{"ha":"Fufu","en":"Fufu"},{"ha":"Garin rogo","en":"Cassava flour"},{"ha":"Garri","en":"Garri"}]$j$::jsonb, 1, $j${"ha":"Ana busar da rogo sosai, sai a niƙa shi ya zama garin rogo.","en":"Cassava is dried well, then ground into cassava flour."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 4, $j${"ha":"Wane ne farin gari da ke zama a ƙasan ruwa?","en":"Which white powder sinks in water?"}$j$::jsonb, $j$[{"ha":"Garri","en":"Garri"},{"ha":"Fufu","en":"Fufu"},{"ha":"Sitaci","en":"Starch"}]$j$::jsonb, 2, $j${"ha":"Sitaci yana zama a ƙasan ruwa, shi ya sa ake iya raba shi.","en":"Starch sinks in water, so it can be separated."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 5, $j${"ha":"Wa ya kamata ya sarrafa rogo a zahiri?","en":"Who should really process cassava?"}$j$::jsonb, $j$[{"ha":"Manya masu horo","en":"Trained adults"},{"ha":"Yaro shi kaɗai","en":"A child alone"},{"ha":"Babu kowa","en":"Nobody"}]$j$::jsonb, 0, $j${"ha":"Manya masu horo ne kawai ya kamata su yi, domin tsaro.","en":"Only trained adults should do it, for safety."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 6, $j${"ha":"Yaya ake samun riba?","en":"How do we find profit?"}$j$::jsonb, $j$[{"ha":"Farashin sayarwa + kuɗin da aka kashe","en":"Selling price + money spent"},{"ha":"Farashin sayarwa − kuɗin da aka kashe","en":"Selling price − money spent"},{"ha":"Kuɗin ƙunshewa kaɗai","en":"Packaging cost only"}]$j$::jsonb, 1, $j${"ha":"Riba = farashin sayarwa − jimillar kuɗin da aka kashe.","en":"Profit = selling price − total money spent."}$j$::jsonb, 5);
    insert into public.missions (slug, mission_no, emoji, title, category_id, stages, reward_rules, engine_options, status)
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'story', null, 0, $j${"emoji":"🧑🏾‍🌾","title":{"ha":"Sannu, ƙaramin mai ƙirƙira! 👋","en":"Hello, young inventor! 👋"},"lines":[{"text":{"ha":"Wata mata mai gona ta girbe dankalin turawa da yawa. Wasu suna fara lalacewa.","en":"A woman farmer harvested lots of potatoes. Some are starting to spoil."}},{"text":{"ha":"Tana son ta san abin da za a iya yi da shi. Za ka iya taimaka mata?","en":"She wants to know what can be made from them. Can you help her?"}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 1, $j${"emoji":"🌍","title":{"ha":"Ka tuna: abu na asali da sabon abu","en":"Remember: resource and new product"},"lines":[{"text":{"ha":"Dankali abu na asali ne. Yana fitowa daga ƙasa.","en":"A potato is a resource. It comes from the soil."}},{"text":{"ha":"Sabon abu ana yin shi daga abu na asali, kamar chips daga dankali.","en":"A new product is made from a resource, like chips from potatoes."}},{"text":{"ha":"Abu na asali → Sarrafawa → Sabon abu → Amfani","en":"Resource → Processing → New product → Value"}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 2, $j${"emoji":"🥔","title":{"ha":"Dankalin turawa","en":"Potato"},"lines":[{"k":"whatIs","text":{"ha":"Tushe ne da ke girma a ƙarƙashin ƙasa. Yana cike da sitaci.","en":"A root that grows under the soil. It is full of starch."}},{"k":"whatDoes","text":{"ha":"Ana ci bayan an dafa shi.","en":"We eat it after it is cooked."}},{"k":"whyNeeded","text":{"ha":"Yana lalacewa idan an ajiye shi da daɗewa. Sarrafawa yana taimakawa.","en":"It spoils when kept too long. Processing helps."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 3, $j${"emoji":"⚠️","warn":true,"title":{"ha":"Tsaro","en":"Safety"},"lines":[{"text":{"ha":"Kada a ci dankalin da ya yi kore ko ya fito da tsiro. Yana iya sa rashin lafiya.","en":"Never eat potatoes that are green or have sprouts. They can make you ill."}},{"text":{"ha":"Mai mai zafi da wuta suna da haɗari. Manya ne kawai ke soya da dafawa. Wannan wasa ne kawai.","en":"Hot oil and fire are dangerous. Only adults fry and boil. This is a game only."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 4, $j${"emoji":"🍟","title":{"ha":"Chips","en":"Chips"},"lines":[{"k":"whatIs","text":{"ha":"Dogayen guntun dankali masu kauri da aka soya.","en":"Thick sticks of potato that are fried."}},{"k":"whatDoes","text":{"ha":"Ana ci da abinci ko da miya.","en":"We eat them with a meal or a sauce."}},{"k":"whyNeeded","text":{"ha":"Soyawa yana ba su ɗanɗano, kuma ana iya sayar da su.","en":"Frying gives them taste, and they can be sold."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 5, $j${"emoji":"🍘","title":{"ha":"Crisps","en":"Crisps"},"lines":[{"k":"whatIs","text":{"ha":"Siraran yankan dankali da aka soya har suka yi ƙwaƙƙwafa.","en":"Very thin potato slices fried until crunchy."}},{"k":"whatDoes","text":{"ha":"Ana ci a matsayin abun ciye-ciye.","en":"Eaten as a snack."}},{"k":"whyNeeded","text":{"ha":"Ana saka musu gishiri don ɗanɗano.","en":"Salt is added for taste."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 6, $j${"emoji":"🌾","title":{"ha":"Garin dankali","en":"Potato flour"},"lines":[{"k":"whatIs","text":{"ha":"Gari mai laushi daga busasshen dankali.","en":"Soft powder from dried potato."}},{"k":"whatDoes","text":{"ha":"Ana amfani da shi a burodi da miya mai kauri.","en":"Used in baking and to thicken soups."}},{"k":"whyNeeded","text":{"ha":"Gari yana daɗewa, ba ya lalacewa da sauri.","en":"Flour lasts long and does not spoil quickly."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 7, $j${"emoji":"🥄","title":{"ha":"Dakakken dankali","en":"Mashed potato"},"lines":[{"k":"whatIs","text":{"ha":"Dankalin da aka dafa aka dake shi ya yi laushi.","en":"Potato that is boiled and mashed until smooth."}},{"k":"whatDoes","text":{"ha":"Ana ci da nama ko kifi.","en":"Eaten with meat or fish."}},{"k":"whyNeeded","text":{"ha":"Hanya ce mai sauƙi ta amfani da dankali kafin ya lalace.","en":"An easy way to use potatoes before they spoil."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 8, $j${"emoji":"💰","title":{"ha":"Sarrafawa yana ƙara ƙima","en":"Processing adds value"},"lines":[{"text":{"ha":"Dankali danye yana da arha kuma yana lalacewa.","en":"Raw potato is cheap and spoils."}},{"text":{"ha":"Chips, crisps, gari da dakakken dankali suna kawo kuɗi.","en":"Chips, crisps, flour and mashed potato can earn money."}},{"text":{"ha":"Kowanne yana da hanyarsa ta musamman. Za ka kalle su duka.","en":"Each has its own special way. You will watch them all."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'wash', 0, $j${"emoji":"🚿","name":{"ha":"Wanke","en":"Wash"},"text":{"ha":"Ana wanke dankali don cire ƙasa.","en":"Potatoes are washed to remove soil."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'peel', 1, $j${"emoji":"🔪","name":{"ha":"Feɗe","en":"Peel"},"text":{"ha":"Manya suna cire bawon dankali.","en":"Adults remove the potato skin."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'cutSticks', 2, $j${"emoji":"🍟","name":{"ha":"Yanka dogayen guda","en":"Cut into sticks"},"text":{"ha":"Ana yanka dankali dogayen guda masu kauri.","en":"Potatoes are cut into thick sticks."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'slice', 3, $j${"emoji":"🥔","name":{"ha":"Yanka siriri-siriri","en":"Slice very thin"},"text":{"ha":"Ana yanka dankali siriri sosai.","en":"Potatoes are sliced very thin."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'rinse', 4, $j${"emoji":"💧","name":{"ha":"Wanke sitaci","en":"Rinse off starch"},"text":{"ha":"Ana wanke yankan a ruwa don cire sitaci mai yawa.","en":"The pieces are rinsed to remove extra starch."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'pat', 5, $j${"emoji":"🧻","name":{"ha":"Shanye ruwa","en":"Pat dry"},"text":{"ha":"Ana shanye ruwa daga yankan don mai kada ya yi tsalle.","en":"The pieces are patted dry so hot oil does not splash."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'fry', 6, $j${"emoji":"🔥","name":{"ha":"Soya a mai","en":"Fry in oil"},"text":{"ha":"Manya suna soya su a mai mai zafi har su yi launin zinariya.","en":"Adults fry them in hot oil until golden."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'season', 7, $j${"emoji":"🧂","name":{"ha":"Saka gishiri","en":"Add salt"},"text":{"ha":"Ana saka ɗan gishiri don ɗanɗano.","en":"A little salt is added for taste."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'pack', 8, $j${"emoji":"📦","name":{"ha":"Ƙunshe","en":"Pack"},"text":{"ha":"Ana saka su a jaka mai tsabta.","en":"They go into a clean bag."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'dry', 9, $j${"emoji":"☀️","name":{"ha":"Busar da shi sosai","en":"Dry it well"},"text":{"ha":"Ana busar da yankan sosai a rana ko da na’ura.","en":"The slices are dried well in the sun or by a machine."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'mill', 10, $j${"emoji":"🏭","name":{"ha":"Niƙa","en":"Grind"},"text":{"ha":"Ana niƙa busasshen dankali ya zama gari.","en":"The dry potato is ground into flour."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'sieve', 11, $j${"emoji":"🧺","name":{"ha":"Tace","en":"Sieve"},"text":{"ha":"Ana tace garin don ya yi laushi.","en":"The flour is sieved to make it smooth."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'boil', 12, $j${"emoji":"♨️","name":{"ha":"Dafa","en":"Boil"},"text":{"ha":"Manya suna dafa dankali a ruwa har ya yi laushi.","en":"Adults boil the potatoes in water until soft."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'mash', 13, $j${"emoji":"🥄","name":{"ha":"Dake","en":"Mash"},"text":{"ha":"Ana dake dankalin har ya yi laushi.","en":"The potatoes are mashed until smooth."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'serve', 14, $j${"emoji":"🍽️","name":{"ha":"Zuba a faranti","en":"Serve"},"text":{"ha":"Ana zuba shi a faranti a ci.","en":"It is served on a plate to eat."}}$j$::jsonb);
