  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'procedure', 'demonstration', 'crisps', 1, $j${"id":"crisps","emoji":"🍘","name":{"ha":"Crisps","en":"Crisps"},"steps":["wash","peel","slice","rinse","pat","fry","season","pack"],"result":{"emoji":"🍘","name":{"ha":"Crisps","en":"Crisps"}},"summary":{"ha":"Crisps: siraran yanka, ana soya su, sa’an nan a saka gishiri.","en":"Crisps: very thin slices, fried, then salted."}}$j$::jsonb);
