  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'challenge', 'drag_drop', 'sort', 0, $j${"type":"sort","key":"sort","items":[{"emoji":"🥔","kind":"resource","name":{"ha":"Dankali a gona","en":"Potato in the field"},"why":{"ha":"Dankali yana girma a ƙasa. Abu na asali ne.","en":"Potatoes grow in the soil. It is a resource."}},{"emoji":"🍟","kind":"product","name":{"ha":"Chips","en":"Chips"},"why":{"ha":"Ana yin chips daga dankali. Sabon abu ne.","en":"Chips are made from potatoes. They are a new product."}},{"emoji":"💧","kind":"resource","name":{"ha":"Ruwa","en":"Water"},"why":{"ha":"Ruwa yana fitowa daga yanayi. Abu na asali ne.","en":"Water comes from nature. It is a resource."}},{"emoji":"🍘","kind":"product","name":{"ha":"Crisps","en":"Crisps"},"why":{"ha":"Ana yin crisps daga siraran dankali. Sabon abu ne.","en":"Crisps are made from thin potato slices. They are a new product."}}]}$j$::jsonb);
