  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 0, $j${"ha":"Me ya sa ba a cin dankalin da ya yi kore ko ya fito da tsiro?","en":"Why do we not eat green or sprouting potatoes?"}$j$::jsonb, $j$[{"ha":"Yana iya sa rashin lafiya","en":"It can make us ill"},{"ha":"Yana da daɗi sosai","en":"It is very tasty"},{"ha":"Yana da tsada","en":"It is expensive"}]$j$::jsonb, 0, $j${"ha":"Dankali kore ko mai tsiro yana iya sa rashin lafiya. Ka jefar da shi.","en":"Green or sprouting potatoes can make you ill. Throw them away."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 1, $j${"ha":"Wane ne ake yankawa siriri sosai, a soya, a saka gishiri?","en":"Which one is sliced very thin, fried and salted?"}$j$::jsonb, $j$[{"ha":"Dakakken dankali","en":"Mashed potato"},{"ha":"Crisps","en":"Crisps"},{"ha":"Garin dankali","en":"Potato flour"}]$j$::jsonb, 1, $j${"ha":"Crisps siraran yanka ne da ake soyawa a saka musu gishiri.","en":"Crisps are thin slices that are fried and then salted."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 2, $j${"ha":"Wane ne ake busarwa a niƙa ya zama gari?","en":"Which one is dried and ground into powder?"}$j$::jsonb, $j$[{"ha":"Garin dankali","en":"Potato flour"},{"ha":"Chips","en":"Chips"},{"ha":"Dakakken dankali","en":"Mashed potato"}]$j$::jsonb, 0, $j${"ha":"Ana busar da yankan dankali sosai, sai a niƙa su ya zama gari.","en":"Potato slices are dried well, then ground into flour."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 3, $j${"ha":"Wane ne ake dafawa a dake, ba a soya shi ba?","en":"Which one is boiled and mashed, not fried?"}$j$::jsonb, $j$[{"ha":"Crisps","en":"Crisps"},{"ha":"Chips","en":"Chips"},{"ha":"Dakakken dankali","en":"Mashed potato"}]$j$::jsonb, 2, $j${"ha":"Ana dafa dankali sai a dake shi. Ba a soya shi.","en":"The potatoes are boiled and then mashed. They are not fried."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 4, $j${"ha":"Wa ya kamata ya soya a mai mai zafi?","en":"Who should fry in hot oil?"}$j$::jsonb, $j$[{"ha":"Manya masu horo","en":"Trained adults"},{"ha":"Yaro shi kaɗai","en":"A child alone"},{"ha":"Babu kowa","en":"Nobody"}]$j$::jsonb, 0, $j${"ha":"Mai mai zafi yana ƙonewa. Manya ne kawai ya kamata su yi.","en":"Hot oil can burn badly. Only adults should do it."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 5, $j${"ha":"Menene sarrafawa ke yi wa dankali?","en":"What does processing do to potatoes?"}$j$::jsonb, $j$[{"ha":"Yana mai da shi sabon abu mai ƙima","en":"Turns it into a new product worth more"},{"ha":"Yana sa ya ɓace","en":"Makes it disappear"},{"ha":"Babu komai","en":"Nothing"}]$j$::jsonb, 0, $j${"ha":"Sarrafawa yana mai da dankali chips, crisps ko gari da za a iya sayarwa.","en":"Processing turns potatoes into chips, crisps or flour that can be sold."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 6, $j${"ha":"Yaya ake samun riba?","en":"How do we find profit?"}$j$::jsonb, $j$[{"ha":"Farashin sayarwa − kuɗin da aka kashe","en":"Selling price − money spent"},{"ha":"Farashin sayarwa + kuɗin da aka kashe","en":"Selling price + money spent"},{"ha":"Kuɗin ƙunshewa kaɗai","en":"Packaging cost only"}]$j$::jsonb, 0, $j${"ha":"Riba = farashin sayarwa − jimillar kuɗin da aka kashe.","en":"Profit = selling price − total money spent."}$j$::jsonb, 5);
    insert into public.missions (slug, mission_no, emoji, title, category_id, stages, reward_rules, engine_options, status)
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'story', null, 0, $j${"emoji":"🧑🏾‍🏫","title":{"ha":"Sannu, ƙaramin mai ƙirƙira! 👋","en":"Hello, young inventor! 👋"},"lines":[{"text":{"ha":"A unguwa an ga shara da yawa: kwalabe, akwatuna, tsofaffin tufafi da gwangwani.","en":"In the neighbourhood there is lots of waste: bottles, boxes, old clothes and cans."}},{"text":{"ha":"Malama tana son ta san yadda za a mai da su abubuwa masu amfani. Za ka iya taimaka mata?","en":"A teacher wants to turn them into useful things. Can you help her?"}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 1, $j${"emoji":"🌍","title":{"ha":"Shara na iya zama abu na asali","en":"Waste can be a resource"},"lines":[{"text":{"ha":"Wasu shara za a iya sake amfani da su. Su ma abu na asali ne.","en":"Some waste can be used again. It is a resource too."}},{"text":{"ha":"Idan an sarrafa su, sai su zama sabon abu mai amfani.","en":"When we process them, they become a useful new product."}},{"text":{"ha":"Abu na asali → Sarrafawa → Sabon abu → Amfani","en":"Resource → Processing → New product → Value"}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 2, $j${"emoji":"♻️","title":{"ha":"Rage, Sake amfani, Sake sarrafawa","en":"Reduce, Reuse, Recycle"},"lines":[{"text":{"ha":"Rage: ka yi ƙarancin shara tun farko.","en":"Reduce: make less waste in the first place."}},{"text":{"ha":"Sake amfani: ka yi amfani da abu sau da yawa maimakon jefarwa.","en":"Reuse: use a thing again instead of throwing it away."}},{"text":{"ha":"Sake sarrafawa: a mai da abu sabon abu.","en":"Recycle: turn a thing into something new."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 3, $j${"emoji":"⚠️","warn":true,"title":{"ha":"Tsaro","en":"Safety"},"lines":[{"text":{"ha":"Kada ka taɓa gilashi da ya karye, abu mai kaifi, ko kwalbar da aka sa sinadari ko magani a ciki. Ka gaya wa babba.","en":"Never touch broken glass, sharp things, or a bottle that held chemicals or medicine. Tell an adult."}},{"text":{"ha":"Kada a ƙone shara. Hayaƙin yana cutarwa. Ka wanke hannu bayan ka taɓa shara. Wannan wasa ne kawai.","en":"Never burn waste. The smoke is harmful. Wash your hands after touching waste. This is a game only."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 4, $j${"emoji":"🧴","title":{"ha":"Kwalbar filastik","en":"Plastic bottle"},"lines":[{"k":"whatIs","text":{"ha":"Kwalbar filastik mara komai da aka gama amfani da ita.","en":"An empty plastic bottle that is finished with."}},{"k":"whatDoes","text":{"ha":"Za a iya mai da ita tukunyar fure.","en":"It can become a flower pot."}},{"k":"whyNeeded","text":{"ha":"Filastik ba ya ruɓewa da sauri, don haka sake amfani yana kare muhalli.","en":"Plastic does not rot quickly, so reusing it protects nature."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 5, $j${"emoji":"📦","title":{"ha":"Akwatin kwali","en":"Cardboard box"},"lines":[{"k":"whatIs","text":{"ha":"Akwatin kwali da aka gama da shi.","en":"A cardboard box that is finished with."}},{"k":"whatDoes","text":{"ha":"Za a iya mai da shi mai ajiye kayan rubutu.","en":"It can become a desk organiser."}},{"k":"whyNeeded","text":{"ha":"Yana taimaka wa tebur ya yi tsabta.","en":"It keeps a desk tidy."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 6, $j${"emoji":"👕","title":{"ha":"Tsohuwar tufafi","en":"Old cloth"},"lines":[{"k":"whatIs","text":{"ha":"Tsohon yadi ko tufafi da ba a sawa.","en":"Old cloth or clothes nobody wears."}},{"k":"whatDoes","text":{"ha":"Za a iya mai da shi jakar yadi.","en":"It can become a cloth bag."}},{"k":"whyNeeded","text":{"ha":"Jakar yadi tana maye gurbin ledar da ake jefarwa.","en":"A cloth bag replaces throw-away plastic bags."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 7, $j${"emoji":"🥫","title":{"ha":"Gwangwani","en":"Tin can"},"lines":[{"k":"whatIs","text":{"ha":"Gwangwani mara komai da aka wanke.","en":"An empty tin can that has been washed."}},{"k":"whatDoes","text":{"ha":"Za a iya mai da shi mariƙin alƙalumma.","en":"It can become a pencil holder."}},{"k":"whyNeeded","text":{"ha":"Gwangwani yana da ƙarfi, don haka yana daɗewa.","en":"A tin can is strong, so it lasts long."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 8, $j${"emoji":"⛽","title":{"ha":"Biogas (iskar girki)","en":"Biogas"},"lines":[{"k":"whatIs","text":{"ha":"Iska ce da ake samu idan ƙananan halittu suka ruɓar da shara ta halitta a cikin rufaffen tanki babu iska.","en":"A gas made when tiny living things break down organic waste inside a sealed tank with no air."}},{"k":"whatDoes","text":{"ha":"Ana amfani da ita wajen girki da hasken wuta, ragowar kuma ta zama taki.","en":"It is used for cooking and lighting, and what is left becomes fertiliser."}},{"k":"whyNeeded","text":{"ha":"Tana rage amfani da itace da gawayi, kuma tana rage shara.","en":"It saves firewood and charcoal and it reduces waste."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 9, $j${"emoji":"⚠️","warn":true,"title":{"ha":"Tsaron biogas","en":"Biogas safety"},"lines":[{"text":{"ha":"Biogas iska ce mai ƙonewa. Kada ka kusanci tankin ko wuta. Masu fasaha masu horo ne kawai ke ginawa da gyara shi.","en":"Biogas is a flammable gas. Never go near the tank or a flame. Only trained technicians build and repair it."}},{"text":{"ha":"Idan ka ji wari mai ƙarfi kamar ruɓaɓɓen ƙwai, ka tafi wuri mai iska ka gaya wa babba. Wannan wasa ne kawai.","en":"If you smell a strong rotten-egg smell, move to fresh air and tell an adult. This is a game only."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 10, $j${"emoji":"♻️","title":{"ha":"Sake sarrafa tsofaffin filastik","en":"Recycling old plastic"},"lines":[{"k":"whatIs","text":{"ha":"Tsofaffin kayan filastik da ake tattarawa, a wanke, a niƙa, sannan a narka a wurin sake sarrafawa.","en":"Old plastic things that are collected, washed, shredded and then melted at a recycling centre."}},{"k":"whatDoes","text":{"ha":"Ana mai da narkakken filastik sabbin kayan yau da kullum, kamar bokiti, kujera da bututu.","en":"The melted plastic is shaped into new everyday things, like buckets, chairs and pipes."}},{"k":"whyNeeded","text":{"ha":"Filastik ba ya ruɓewa da sauri, don haka sake sarrafa shi yana rage shara a muhalli.","en":"Plastic does not rot quickly, so recycling it reduces waste in nature."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 11, $j${"emoji":"🔢","title":{"ha":"Nau’o’in filastik","en":"Types of plastic"},"lines":[{"text":{"ha":"Filastik iri-iri ne. Ana raba su da nau’insu kafin a narka su.","en":"There are many kinds of plastic. They are sorted by type before melting."}},{"text":{"ha":"Lambar da ke ƙasan kwalba ko bokiti tana nuna nau’in filastik ɗin.","en":"The number on the bottom of a bottle or bucket shows its type of plastic."}},{"text":{"ha":"Ba a haɗa nau’o’i daban-daban tare, don sabon abu ya yi ƙarfi.","en":"Different types are not mixed, so the new product stays strong."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 12, $j${"emoji":"⚠️","warn":true,"title":{"ha":"Tsaron narka filastik","en":"Plastic melting safety"},"lines":[{"text":{"ha":"Narka ko ƙone filastik yana fitar da hayaƙi mai guba da zafi mai haɗari.","en":"Melting or burning plastic gives off toxic smoke and dangerous heat."}},{"text":{"ha":"Manya masu horo ne kawai ke yi, a wuri mai iska kuma da kayan kariya. Kada ka narka ko ƙone filastik a gida. Wannan wasa ne kawai.","en":"Only trained adults do it, in a ventilated place with protective gear. Never melt or burn plastic at home. This is a game only."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 13, $j${"emoji":"💰","title":{"ha":"Sarrafawa yana ƙara ƙima","en":"Processing adds value"},"lines":[{"text":{"ha":"Shara tana da arha ko kyauta. Sabon abu da aka yi daga gare ta ana iya sayarwa ko amfani da shi.","en":"Waste is cheap or free. A new product made from it can be sold or used."}},{"text":{"ha":"Kowanne yana da hanyarsa. Wasu matakai na manya ne kawai. Za ka kalle su duka.","en":"Each has its own way. Some steps are for adults only. You will watch them all."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'collectBottle', 0, $j${"emoji":"🧴","name":{"ha":"Tattara kwalba","en":"Collect a bottle"},"text":{"ha":"Ana tattara kwalbar filastik mara komai.","en":"Collect an empty plastic bottle."},"kid":true}$j$::jsonb);
