  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'cutBottle', 2, $j${"emoji":"✂️","name":{"ha":"Yanka kwalba","en":"Cut the bottle"},"text":{"ha":"Babba ne ke yanka kwalbar da kayan aiki masu kaifi.","en":"An adult cuts the bottle with sharp tools."}}$j$::jsonb);
